from pathlib import Path
from PIL import Image
import hashlib,json,re

B=Path(__file__).parent
POSES=['idle','walk-a','carry-or-work','walk-b']
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
reg=json.loads((B/'registration-evidence.json').read_text())
checks=[]
for pose in POSES:
    d=B/pose; q=json.loads((d/'alpha-qa.json').read_text());req=json.loads((d/'request.json').read_text());result=json.loads((d/'generation-result.json').read_text())
    source=Path(result.get('originalGeneratedPath') or re.search(r'as (/\S+\.png) by default',result['output_hint']).group(1))
    result['originalGeneratedPath']=str(source);(d/'generation-result.json').write_text(json.dumps(result,indent=2)+'\n')
    prov=json.loads((d/'request-provenance.json').read_text());prov['originalGeneratedPath']=str(source);prov['originalNativeRawMasterHashes']={'originalGenerated':sha(source),'native':sha(d/'native.png'),'raw':sha(d/'raw.png'),'master':sha(d/'master.png')};prov['originalNativeRawMasterIdentical']=len(set(prov['originalNativeRawMasterHashes'].values()))==1
    (d/'request-provenance.json').write_text(json.dumps(prov,indent=2)+'\n')
    check={'pose':pose,'originalNativeRawMasterIdentical':prov['originalNativeRawMasterIdentical'],'promptExactlyMatchesRequest':(d/'prompt.txt').read_text().rstrip('\n')==req['prompt'],'realRgba':q['mode']=='RGBA','perimeterAlphaAtMost1':q['perimeterMaxAlpha']<=1,'wholeCanvasFits':reg['poses'][pose]['wholeCanvasFitsProposedFrame'],'offsetAtMost2':max(abs(x) for x in reg['poses'][pose]['registrationOffsetLogical'])<=2}
    assert all(check[k] for k in check if k!='pose'),check
    checks.append(check)
rejected=B/'walk-b/rejected-attempt-01'
req=json.loads((rejected/'request.json').read_text());rejprov={'tool':'built-in image_gen.imagegen','status':'rejected-not-selected','reason':'Same stride phase as walk-a; replacement required.','promptFileSha256':sha(rejected/'prompt.txt'),'requestFileSha256':sha(rejected/'request.json'),'rawSha256':sha(rejected/'raw.png'),'masterSha256':sha(rejected/'master.png'),'rawMasterIdentical':sha(rejected/'raw.png')==sha(rejected/'master.png'),'references':[{'path':p,'sha256':sha(Path(p))} for p in req['referenced_image_paths']]}
(rejected/'request-provenance.json').write_text(json.dumps(rejprov,indent=2)+'\n')
config={'topicId':'C01-MISSION-CONTROLLED-SOLDIER','frames':{p:str(B/p/'master.png') for p in POSES},'scale':reg['sharedScale'],'origin':reg['proposedOrigin'],'frameSize':reg['proposedCommonFrameSize'],'sourceFoot':reg['canonicalSourceFoot'],'sourceFeet':{p:r['sourceSupportAnchor'] for p,r in reg['poses'].items()},'registrationOffsets':{p:r['registrationOffsetLogical'] for p,r in reg['poses'].items()},'registrationLimit':2,'canvasPaddingTolerance':2}
(B/'qa-export-config.json').write_text(json.dumps(config,indent=2)+'\n')
frames=[]
for p in POSES:
    im=Image.open(B/f'qa-export/{p}@1x.png');canvas=Image.new('RGBA',(104,64),(109,126,93,255));canvas.alpha_composite(im);frames.append(canvas.convert('RGB'))
frames[0].save(B/'qa-sequence.gif',save_all=True,append_images=frames[1:],duration=220,loop=0,disposal=2)
review={'topicId':'C01-MISSION-CONTROLLED-SOLDIER','workerStatus':'complete; coordinator final visual gate pending','consumerStatus':'catalog-only','frames':POSES,'functionalPalettePreserved':True,'controlCue':'Original physical ochre-gold collar and both wrist bands visible throughout. No glow, magic, invented faction emblem or weapon.','identity':'Worried clean-shaven young man, large gray riveted helmet, segmented gray armor, charcoal trousers, dark brown belt and boots, two empty bare hands.','poseReview':{'idle':'Original upright worried stance, arms low.','walk-a':'Screen-right far boot forward, screen-left near boot trailing. Both hands swing; control bands intact.','carry-or-work':'Tense unarmed on-duty attention; both empty fists inward beside belt, both gold cuffs visible. Original stationary work-role grounded, no invented props.','walk-b':'Complementary phase: screen-left near boot planted toward viewer and screen-right far boot lifted back. Maintains screen-right facing without mirroring.'},'rejectedAttempts':[{'path':'walk-b/rejected-attempt-01','reason':'Walk-b repeated walk-a stride rather than opposite phase. Native bytes and request preserved.'}],'notGeneratedPlans':[{'path':'planning/cuff-inspection-superseded-not-generated','reason':'Optional cuff-inspection concept superseded by coordinator before generation; not selected work-role.'}],'technicalChecks':checks,'commonSourceCanvas':reg['commonSourceCanvas'],'maximumCanvasPadding':reg['canvasPaddingToleranceRequired'],'fixedScale':reg['sharedScale'],'maximumSupportTranslationLogical':reg['requiredMaximumTranslationLogicalPixels'],'runtimeDiagnosticFrameSize':[104,64],'runtimeDiagnosticOrigin':[8,4],'repositoryWrites':False,'nativeByteEdits':False,'perFrameFitting':False,'nativeGif':'qa-walk-6.25fps.gif','allPoseGif':'qa-sequence.gif','threeBackgroundReview':'qa-native44-three-backgrounds-3x.png','visualReview':'Native masters inspected against original and approved family. 1x/3x on black/white/scene inspected for role, silhouette, full margins and alpha. Four-frame montage confirms distinct work gesture and complementary walks. GIF generated from the same registered native frames.'}
(B/'qa-review.json').write_text(json.dumps(review,indent=2)+'\n')
manifest={'topicId':'C01-MISSION-CONTROLLED-SOLDIER','assetId':'C01-FFV1-MISSION-CONTROLLED-SOLDIER','label':'被控制的普通士兵','generator':'built-in image_gen.imagegen','consumerStatus':'catalog-only','status':'ready-for-coordinator-review','frameOrder':POSES,'frames':{p:{'master':f'{p}/master.png','raw':f'{p}/raw.png','native':f'{p}/native.png','request':f'{p}/request.json','prompt':f'{p}/prompt.txt','qa':f'{p}/alpha-qa.json','provenance':f'{p}/request-provenance.json'} for p in POSES},'registration':'registration-evidence.json','fixedScale':reg['sharedScale'],'bodyTargetHeightLogicalPixels':44,'commonSourceCanvas':reg['commonSourceCanvas'],'frameSize':[104,64],'origin':[8,4],'sourceFoot':reg['canonicalSourceFoot'],'anchor':reg['proposedAnchor'],'registrationLimit':2,'canvasPaddingTolerance':2,'sourceEvidence':'source-evidence.json','qaReview':'qa-review.json','selectedNativeMasterCount':4,'generatedNativeOutputCount':5,'rejectedNativeOutputCount':1,'scope':'Native authored masters and diagnostic technical exports only. No repository edits or runtime consumer claims.'}
(B/'bundle-manifest.json').write_text(json.dumps(manifest,indent=2)+'\n')
(B/'SHA256SUMS.json').write_text(json.dumps({str(p.relative_to(B)):sha(p) for p in sorted(B.rglob('*')) if p.is_file() and p.name!='SHA256SUMS.json'},indent=2)+'\n')
print(json.dumps({'checks':checks,'filesHashed':len(json.loads((B/'SHA256SUMS.json').read_text())),'maximumSupportOffset':reg['requiredMaximumTranslationLogicalPixels'],'maximumCanvasPadding':reg['canvasPaddingToleranceRequired']},indent=2))
